<script>document.addEventListener('DOMContentLoaded',function(){const form=document.querySelector('form[action*="inventory.documents.store"]');const type=form?.querySelector('[name="document_type"]');const submit=form?.querySelector('button[type="submit"],button.btn-primary');if(form&&submit){const wrapper=document.createElement('div');wrapper.className='form-check mb-3';wrapper.innerHTML='<input name="inspection_required" value="1" type="checkbox" class="form-check-input" id="inspection-required"><label class="form-check-label" for="inspection-required">Require quality inspection for this receipt</label>';submit.parentNode.parentNode.insertBefore(wrapper,submit.parentNode);const sync=()=>{wrapper.style.display=type?.value==='receipt'?'block':'none';};type?.addEventListener('change',sync);sync();}});</script>
